    public static bool Has(string table) => Fields.ContainsKey(table);

    /// <summary>The kind of a field of these tables where it is a length, force or moment in the model's units (eccentricity
    /// overwrites, exposure widths and ordinates, parapet height, user loads, control displacement), else null.</summary>
    public static ModelUnits.Dim? FieldDim(string table, string field)
    {
        if (!Has(table)) return null;
        return field switch
        {
            "OverEcc" or "OverEccen" or "ParapetHt" or "Width" or "Depth" or "X" or "Y" or "DisplTrans" or "UserZ" => ModelUnits.Dim.Len,
            "Fx" or "Fy" or "Fz" or "FX" or "FY" or "FZ" => ModelUnits.Dim.Force,
            "Mx" or "My" or "Mz" or "MX" or "MY" or "MZ" => ModelUnits.Dim.Moment,
            _ => ModelUnits.Dim.None,
        };
    }

    private const string Seismic = "Load Pattern Definitions - Auto Seismic - ", Wind = "Load Pattern Definitions - Auto Wind - ";

    /// <summary>The code a table is for, as ETABS's AutoLoad field takes it (the table key's own words, e.g. "KDS 41 17 00:2019"), or null.</summary>
    public static string? Code(string table) =>
        table.StartsWith(Seismic, StringComparison.OrdinalIgnoreCase) ? table[Seismic.Length..] : table.StartsWith(Wind, StringComparison.OrdinalIgnoreCase) ? table[Wind.Length..] : null;

    /// <summary>Each pattern with rows in a code's table, and the code ETABS's "Load Pattern Definitions" AutoLoad takes for it.</summary>
    public static Dictionary<string, string> AutoLoads(StructuralModel m)
    {
        var o = new Dictionary<string, string>(StringComparer.Ordinal);
        foreach (var (table, rows) in m.DefinitionTables ?? [])
            if (Code(table) is { } code)
                foreach (var r in rows)
                    if (r.GetValueOrDefault("Name") is { Length: > 0 } n) o[n] = code;
        return o;
    }

    /// <summary>A pattern's code rows taken out (Auto Lateral Load set to None or another code): every code table but <paramref name="keep"/>.</summary>
    public static void ClearCode(StructuralModel m, string pattern, string? keep = null)
    {
        if (m.DefinitionTables is null) return;
        foreach (var table in m.DefinitionTables.Keys.Where(t => Code(t) is not null && !t.Equals(keep, StringComparison.OrdinalIgnoreCase)).ToList())
        {
            m.DefinitionTables[table].RemoveAll(r => r.GetValueOrDefault("Name") == pattern);
            if (m.DefinitionTables[table].Count == 0) m.DefinitionTables.Remove(table);
        }
        // The pattern's own auto load line of the .e2k it was read from (SEISMIC / WIND "pattern" ...) goes too: the
        // form set it anew, and ETABS would otherwise read the old code before the new table rows.
        if (m.UnparsedLines is { } lines)
            foreach (var list in lines.Values)
                list.RemoveAll(l => Regex.IsMatch(l, "^\\s*(SEISMIC|WIND)\\s+\"" + Regex.Escape(pattern) + "\"", RegexOptions.IgnoreCase));
        if (m.DefinitionTables.Count == 0) m.DefinitionTables = null;
    }

    /// <summary>A pattern or case renamed ("pattern", "case"): its rows, and the rows naming it, follow.</summary>
    public static void Rename(StructuralModel m, string kind, string was, string name)
    {
        if (was == name || m.DefinitionTables is null) return;
        foreach (var (table, rows) in m.DefinitionTables.Where(x => Has(x.Key)))
            foreach (var r in rows)
            {
                void Swap(string f) { if (r.TryGetValue(f, out var v) && v == was) r[f] = name; }
                var patternTable = table.StartsWith("Load Pattern Definitions", StringComparison.OrdinalIgnoreCase);
                if (kind == "pattern")
                {
                    if (patternTable) { Swap("Name"); Swap("LoadPattern"); Swap("BasePattern"); }
                    else
                    {
                        if (r.GetValueOrDefault("LoadType") is not { } lt || lt.StartsWith("Load", StringComparison.OrdinalIgnoreCase)) Swap("LoadName");
                        if (r.GetValueOrDefault("ItemType") is { } it && it.StartsWith("Load", StringComparison.OrdinalIgnoreCase)) Swap("ItemName");
                    }
                }
                else if (kind == "case" && !patternTable)
                {
                    Swap("Name"); Swap("NonlinCase"); Swap("InitialCond"); Swap("ModalCase"); Swap("BaseCase");
                    if (r.GetValueOrDefault("LoadType") is { } lt && lt.Contains("Case", StringComparison.OrdinalIgnoreCase)) Swap("LoadName");
                }
            }
    }

    /// <summary>A pattern or case deleted: its own rows go (rows of other definitions naming it are left for ETABS to refuse).</summary>
    public static void Drop(StructuralModel m, string kind, string name)
    {
        if (m.DefinitionTables is null) return;
        foreach (var table in m.DefinitionTables.Keys.Where(Has).ToList())
        {
            var patternTable = table.StartsWith("Load Pattern Definitions", StringComparison.OrdinalIgnoreCase);
            if (patternTable != (kind == "pattern")) continue;
            m.DefinitionTables[table].RemoveAll(r => (r.GetValueOrDefault("Name") ?? r.GetValueOrDefault("LoadPattern")) == name);
            if (m.DefinitionTables[table].Count == 0) m.DefinitionTables.Remove(table);
        }
        if (m.DefinitionTables.Count == 0) m.DefinitionTables = null;
    }
}
